={{ JSON.stringify((() => {
  const obj = $json.body.data.object;
  const amountTotal = Number(obj.amount || obj.amount_received || 0) / 100;
  const currency = (obj.currency || 'gbp').toUpperCase();
  const symbol = currency === 'GBP' ? '£' : (currency === 'EUR' ? '€' : '$');
  const customerName = (obj.shipping && obj.shipping.name) || obj.customer_email || obj.receipt_email || 'Unknown';
  const customerEmail = obj.receipt_email || obj.customer_email || 'N/A';
  const paymentMethod = obj.payment_method_types ? obj.payment_method_types[0] : 'N/A';
  const description = obj.description || obj.statement_descriptor || 'N/A';
  const createdAt = obj.created ? new Date(obj.created * 1000).toLocaleString('en-GB', { timeZone: 'Europe/London' }) : 'N/A';
  const paymentId = obj.id || 'N/A';
  const stripeLink = obj.id ? 'https://dashboard.stripe.com/payments/' + obj.id : null;
  return {
    channel: 'C0A69CWFJN9',
    text: '💰 Stripe payment received from ' + customerName,
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: '💰 Payment Received — Stripe', emoji: true } },
      { type: 'section', text: { type: 'mrkdwn', text: 'You just received a payment of *' + symbol + amountTotal.toFixed(2) + ' ' + currency + '* from *' + customerName + '*.' } },
      { type: 'divider' },
      { type: 'section', fields: [
        { type: 'mrkdwn', text: '*Customer*\\n' + customerName },
        { type: 'mrkdwn', text: '*Amount*\\n' + symbol + amountTotal.toFixed(2) + ' ' + currency },
        { type: 'mrkdwn', text: '*Email*\\n' + customerEmail },
        { type: 'mrkdwn', text: '*Payment Method*\\n' + paymentMethod.charAt(0).toUpperCase() + paymentMethod.slice(1) },
        { type: 'mrkdwn', text: '*Description*\\n' + description },
        { type: 'mrkdwn', text: '*Status*\\n✅ Succeeded' },
        { type: 'mrkdwn', text: '*Created At*\\n' + createdAt },
        { type: 'mrkdwn', text: '*Payment ID*\\n' + paymentId }
      ]},
      { type: 'divider' },
      ...(stripeLink ? [{ type: 'section', text: { type: 'mrkdwn', text: '<' + stripeLink + '|View in Stripe Dashboard>' } }] : []),
      { type: 'context', elements: [{ type: 'mrkdwn', text: 'Stripe · Property Hussle · ' + new Date().toISOString() }] }
    ]
  };
})()) }}

